    // source-level aliases accepted by the compiler
    (0, "FINISH", 0),
    (44, "MOUSEACT", 1),
];

pub fn op_info(op: i32) -> Option<(&'static str, usize)> {
    OPS.iter().find(|o| o.0 == op).map(|o| (o.1, o.2))
}

pub fn opcode_of(name: &str) -> Option<i32> {
    OPS.iter().find(|o| o.1 == name).map(|o| o.0)
}

