char msg_insert_disk[100] = "Please make sure that Donald's Alphabet Chase disk is in the disk drive, then press the space bar.";

/* Uninitialised data (_BSS): DGROUP 3868-3AE3 (ownership inferred, see agents/docs/MATCHING.md). */
int jump_right;
int slot_x[NUM_SLOTS];
int slot_y[NUM_SLOTS];
int g_group;
int slot_frame[NUM_SLOTS];
int jump_x_major;
int slot_shown[NUM_SLOTS];
int jump_major;
int jump_minor;
int g_keysEnabled;
char far *g_packBuf;
int jump_steps;
script_t far *slot_pc[NUM_SLOTS];
int g_letterPicked;
int jump_err;
int g_idleTicks;
int g_pickedLetter;
char unused_38E2[40];
int slot_delay[NUM_SLOTS];
int g_gameWon;
int slot_w[NUM_SLOTS];
int slot_timer[NUM_SLOTS];
char far *g_workBuf;
int g_letterDone[NUM_LETTERS];
int slot_flag[NUM_SLOTS];
char far *g_sprites[NUM_SPRITES];
char unused_3A9C[2];
int slot_h[NUM_SLOTS];
int g_letterScore[NUM_LETTERS];
int g_jumping;

/* FUNCTION: DONALD 0304:000C */
void present_rect(char far *src, register int x, register int y, int w, int h)
{
    if (g_videoMode != VM_EGA)
        blit_generic(x, y, w, h >> 3, src);
    else
        blit_ega(x, y, x, y, w, h >> 3, (char far *)0xA8000000L, (char far *)0xA0000000L);
}

/* FUNCTION: DONALD 0304:0066 */
void propagate_dirty_overlap(void)
{
    register int i;
    register int j;
    int x1, x2, y1, y2, ox1, ox2, oy1, oy2, k;

    for (k = 0; k < 8; k++)
        for (i = 0; i < NUM_SLOTS; i++) {
            if (slot_shown[i] == -1)
                continue;
            for (j = 0; j < NUM_SLOTS; j++) {
                if (j == i)
                    continue;
                x1 = (slot_x[i] >> 3) - 1;
                x2 = slot_w[i] + x1 + 2;
                y1 = (slot_y[i] >> 3) - 1;
                y2 = slot_h[i] + y1 + 2;
                ox1 = slot_x[j] >> 3;
                ox2 = slot_w[j] + ox1;
                oy1 = slot_y[j] >> 3;
                oy2 = slot_h[j] + oy1;
                if (slot_h[i] != 3 && slot_h[i] != 8) {
                    x1--;
                    x2++;
                }
                if (x1 <= ox2 && x2 >= ox1 && y1 <= oy2 && y2 >= oy1)
                    slot_shown[j] = slot_frame[j];
            }
        }
}

/* FUNCTION: DONALD 0304:0187 */
void copy_dirty_actor_rects(int mode)
{
    register int i;
    register int grow;
    int padX, padY;

    for (i = 0; i < NUM_SLOTS; i++) {
        padX = 1;
        padY = 8;
        grow = 2;
        if (slot_h[i] != 3 && slot_h[i] != 8) {
            padX = grow;
            padY = 16;
            grow = 4;
        }
        if (slot_shown[i] != -1)
            copy_page_rect(mode, (slot_x[i] >> 3) - padX, slot_y[i] - padY, slot_w[i] + grow, (slot_h[i] + grow) << 3);
    }
}

/* FUNCTION: DONALD 0304:0221 */
void copy_page_rect(int mode, register int x, register int y, int w, int h)
{
    char far *src;
    char far *dst;

    while (x < 0) {
        x++;
        w--;
    }
    while (y < 0) {
        y++;
        h--;
    }
    if (w <= 0)
        return;
    if (h <= 0)
        return;
    switch (mode) {
    case PAGE_SCREEN_TO_BACK:
        src = (char far *)0xA0000000L;
        dst = (char far *)0xA8000000L;
        break;
    case PAGE_BACK_TO_SCREEN:
        src = (char far *)0xA8000000L;
        dst = (char far *)0xA0000000L;
        break;
    case PAGE_BACK_TO_WORK:
        src = (char far *)0xA8000000L;
        dst = (char far *)0xA4000000L;
        break;
    case PAGE_WORK_TO_BACK:
        src = (char far *)0xA4000000L;
        dst = (char far *)0xA8000000L;
        break;
    case PAGE_SCREEN_TO_WORK:
        src = (char far *)0xA0000000L;
        dst = (char far *)0xA4000000L;
        break;
    case PAGE_WORK_TO_SCREEN:
        src = (char far *)0xA4000000L;
        dst = (char far *)0xA0000000L;
        break;
    }
    if (g_videoMode != VM_EGA) {
        switch (mode) {
        case PAGE_SCREEN_TO_BACK:
            src = g_videoMem;
            dst = g_backBuf;
            break;
        case PAGE_BACK_TO_SCREEN:
            src = g_backBuf;
            dst = g_videoMem;
            break;
        case PAGE_BACK_TO_WORK:
            src = g_backBuf;
            dst = g_workBuf;
            break;
        case PAGE_WORK_TO_BACK:
            src = g_workBuf;
            dst = g_backBuf;
            break;
        case PAGE_SCREEN_TO_WORK:
            src = g_videoMem;
            dst = g_workBuf;
            break;
        case PAGE_WORK_TO_SCREEN:
            src = g_workBuf;
            dst = g_videoMem;
            break;
        }
    }
    copy_rect_ega(src, dst, x, y, w, h);
}

/* FUNCTION: DONALD 0304:0383 */
void step_jump_path(register int i)
{
    if (jump_x_major) {
        if (jump_right)
            slot_x[i] += 8;
        else
            slot_x[i] -= 8;
    } else
        slot_y[i] -= 8;
    jump_err -= jump_minor;
    if (jump_err < 0) {
        jump_err += jump_major;
        if (!jump_x_major) {
            if (jump_right)
                slot_x[i] += 8;
            else
                slot_x[i] -= 8;
        } else
            slot_y[i] -= 8;
    }
}

/* FUNCTION: DONALD 0304:03FC */
void draw_actor_frame(int mode, register int i, register int x, int y)
{
    char far *p;

    p = g_backBuf;
    if (g_videoMode == VM_EGA)
        p = (char far *)0xA8000000L;
    g_windows[1].x = 0;
    g_windows[1].w = 40;
    g_windows[1].y = 0;
    g_windows[1].h = 25;
    switch (mode) {
    case DRAW_SCREEN:
        draw_sprite(g_videoMem, g_sprites[i], x, y, 1);
        break;
    case DRAW_BACK:
        draw_sprite(p, g_sprites[i], x, y, 1);
        break;
    case DRAW_BACK_MIRRORED:
        draw_sprite_mirrored(p, g_sprites[i], x, y, 1);
        break;
    case DRAW_SCREEN_MIRRORED:
        draw_sprite_mirrored(g_videoMem, g_sprites[i], x, y, 1);
        break;
    }
}

/* FUNCTION: DONALD 0304:04F9 */
void next_level(void)
{
    char i, sum;

    for (i = sum = 0; i < NUM_LETTERS; i++)
        sum += g_letterScore[i];
    if (sum < NUM_LETTERS) {
        do {
            g_group++;
            if (g_group >= NUM_GROUPS)
                g_group = 0;
            sum = 0;
            for (i = g_groupFirst[g_group]; i < g_groupFirst[g_group + 1]; i++)
                sum += g_letterScore[i];
        } while (sum == group_letter_count[g_group]);
        i = 0;
        if (key_ready())
            i = handle_key();
        if (i == 0 || i == KEY_ESC) {
            load_level_gfx();
            reset_actors();
        }
    } else
        g_gameWon = 1;
}

/* FUNCTION: DONALD 0304:05C0 */
int detect_tandy_signature(void)
{
    register int r = 0;
    char c = 0;

    c = *(char far *)0xF000C000L;
    if (c == 0x21)
        r = 1;
    return r;
}

/* FUNCTION: DONALD 0304:05EB */
void detect_video(void)
{
    register int i;
    long t0, t1;

    set_text_mode();
    for (i = 0; i < 8; i++) {
        dos_putc(str_lf);
        dos_putc(str_cr);
    }
    i = 0;
    if (detect_tandy_signature()) {
        g_videoMode = VM_TANDY;
        while (msg_tandy[i])
            dos_putc(msg_tandy[i++]);
    } else if (ega_present()) {
        g_videoMode = VM_EGA;
        while (msg_ega[i])
            dos_putc(msg_ega[i++]);
    } else {
        g_videoMode = VM_CGA;
        while (msg_cga[i])
            dos_putc(msg_cga[i++]);
    }
    i = 0;
    while (msg_detected[i])
        dos_putc(msg_detected[i++]);
    i = 0;
    time(&t0);
    do {
        if (key_ready())
            i = get_key();
        time(&t1);
    } while (!i && t1 - t0 < 20);
    time(&g_randSeed);
