/* FUNCTION: DONALD 0304:1061 */
int handle_key(void)
{
    register int key = 0;
    register int r;

    if (!g_keysEnabled) {
        kbd_flush();
        goto done;
    }
    if (key_ready()) {
        key = get_key();
        kbd_flush();
        if (key >= 'a' && key <= 'z')
            key = key - 32;
        if ((key < 'A' || key > 'Z') && key != KEY_ESC && key != KEY_SOUND)
            key = 0;
    }
    if (key && key != KEY_ESC && !g_letterPicked && key != KEY_SOUND) {
        r = completed_group_score();
        if (r)
            goto done;
        key -= 'A';
        if (g_letterScore[key])
            goto clear;
        g_idleTicks = 0;
        for (r = 5; r >= 0; r--)
            if (g_groupFirst[r] <= key)
                break;
        if (r != g_group) {
            g_group = r;
            load_level_gfx();
            reset_actors();
        } else if (key != g_curLetter)
            prepare_letter_selection(key);
        else
            play_sound(0);
        g_curLetter = g_pickedLetter = key;
        g_letterPicked = 1;
        g_letterDone[g_pickedLetter] = 1;
        slot_pc[SLOT_BUBBLE] = g_scriptTable[SCR_BUBBLE];
        bubble_arg2 = 0;
        bubble_arg1 = 3;
        bubble_frame = (key - g_groupFirst[g_group]) * 4 + 1;
        goto done;
    }
    if (key != KEY_SOUND)
        goto done;
    snd_play(g_tunes[4]);
    g_soundOn ^= 1;
    if (!g_soundOn)
        stop_sound();
clear:
    key = 0;
done:
    return key;
}

