namespace corncob::game {

namespace d = corncob::dgroup;
using asmx::bndck;
using asmx::hmul;
using asmx::sf16;
using engine::atn2;
using engine::scos;
using engine::ssin;
namespace lbl = corncob::lbl;

const u32 Main3::SCNCODE = d::m3::scncode;

