Main3::Main3(GameState& gs, engine::F3dVec& eng, World& world, DosKeyboard& kbd, TickClock& clock,
             Instruments& inst)
    : m_g(gs), m_eng(eng), m_world(world), m_kbd(kbd), m_clock(clock), m_inst(inst) {
    m_eng.setHooks(this);
    m_eng.setTickSource(&m_clock.oticks);
}

// ---- wtadj / uwtadj / dwtadj (3DMAC.INC) ----
// wtadj truncated: at a short frame the small amounts the original handed it (a few units) lost a third or more of their
// value, always in the same direction. The remainder is dithered instead (a low-discrepancy sequence), so on average the
// full amount comes through whatever the frame length.
i16 Main3::wtadj(i16 v) const {
    const int den = W(M3(ticksf));
    if (den <= 0) return v;
    m_dither = (m_dither + 25) % static_cast<u32>(den);   // 25/40 ~ the golden ratio
    const int64_t num = static_cast<int64_t>(v) * W(M3(ofrmticks)) + static_cast<int64_t>(m_dither);
    int64_t q = num / den;
    if (num % den < 0) q--;   // floor
    return static_cast<i16>(std::max<int64_t>(-32768, std::min<int64_t>(32767, q)));
}
i16 Main3::uwtadj(i16 v) const { return asmx::uwtadj(v, W(M3(ofrmticks)), W(M3(ticksf))); }
i32 Main3::dwtadj(i32 v) const {
    return sas::divrs_dw(sas::muls_dw(v, W(M3(ofrmticks))), W(M3(ticksf)));
}

i32 Main3::dwtadjWide(i32 v) const {
    const i16 den = W(M3(ticksf));
    if (den == 0) return v;
    const int64_t num = static_cast<int64_t>(v) * W(M3(ofrmticks));
    const int64_t half = den / 2;
    const int64_t q = (num >= 0 ? num + half : num - half) / den;   // rounded to nearest
    return static_cast<i32>(std::max<int64_t>(INT32_MIN, std::min<int64_t>(INT32_MAX, q)));
}

i32 Main3::frameScale(i32 v) const {
    const int64_t num = static_cast<int64_t>(v) * W(M3(ofrmticks));
    const int64_t q = (num >= 0 ? num + REF_TICKS / 2 : num - REF_TICKS / 2) / REF_TICKS;
    return static_cast<i32>(std::max<int64_t>(INT32_MIN, std::min<int64_t>(INT32_MAX, q)));
}

i32 Main3::decayStep(i32 v, double keep) const {
    if (keep <= 0.0 || keep >= 1.0) return v;
    const double f = static_cast<double>(W(M3(ofrmticks))) / REF_TICKS;
    return static_cast<i32>(std::lround(static_cast<double>(v) * std::pow(keep, f)));
}

u16 Main3::dispScale(u16 range) const {
    if (range == 0) return 0;
    const double f = static_cast<double>(W(M3(ofrmticks))) / REF_TICKS;
    return static_cast<u16>(std::max(1L, std::lround(range * std::sqrt(f))));
}

i16 Main3::keepPow15(i16 keep15) const {
    if (keep15 <= 0) return keep15;
    const double f = static_cast<double>(W(M3(ofrmticks))) / REF_TICKS;
    const long r = std::lround(32768.0 * std::pow(keep15 / 32768.0, f));
    return static_cast<i16>(std::min<long>(r, 32767));
}

i16 Main3::takeWhole(i32 value, u16& frac) {
    const int64_t total = static_cast<int64_t>(value) + frac;
    frac = static_cast<u16>(total & 0xFFFF);
    const int64_t whole = total >> 16;
    return static_cast<i16>(std::max<int64_t>(-32768, std::min<int64_t>(32767, whole)));
}

void Main3::velmul(u16 si, u16 bx, u16 di) {
    for (int k = 0; k < 3; k++) {
        int64_t sum = 0;
        for (int j = 0; j < 3; j++) sum += static_cast<int64_t>(W(si + 2 * j)) * W(bx + 6 * k + 2 * j);
        const int64_t r = (sum + 0x4000) >> 15;   // 1.15, rounded
        SW(di + 2 * k, static_cast<i16>(std::max<int64_t>(-32767, std::min<int64_t>(32767, r))));
